// ── Excel Export Helper with Embedded Logo ──
async function exportExcelWithLogo(workbookTitle, headers, rows, filename) {
  try {
    if (typeof ExcelJS === 'undefined') {
      window.showToast('Excel exporter library is loading, please try again in a moment.', 'info');
      return;
    }

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Report');

    // Add Logo to workbook
    const b64Data = APP_LOGO_DATA_URI.split(',')[1];
    const imageId = workbook.addImage({
      base64: b64Data,
      extension: 'png'
    });

    // Position logo at Top Left (Col 1-2, Row 1-3)
    worksheet.addImage(imageId, {
      tl: { col: 0, row: 0 },
      ext: { width: 150, height: 40 }
    });

    // Title Block
    worksheet.getRow(1).height = 25;
    worksheet.getRow(2).height = 22;

    worksheet.getCell('C1').value = 'DMCH RESTO - DREAM MEDICAL CENTER HOSPITAL';
    worksheet.getCell('C1').font = { bold: true, size: 13, color: { argb: 'FF0F172A' } };

    worksheet.getCell('C2').value = workbookTitle;
    worksheet.getCell('C2').font = { bold: true, size: 11, color: { argb: 'FFF59E0B' } };

    worksheet.getCell('C3').value = `Generated: ${new Date().toLocaleString()}`;
    worksheet.getCell('C3').font = { italic: true, size: 9, color: { argb: 'FF64748B' } };

    // Blank row spacer
    worksheet.addRow([]);

    // Header Row
    const headerRow = worksheet.addRow(headers);
    headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
    headerRow.eachCell(cell => {
      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'FF0F172A' }
      };
      cell.alignment = { vertical: 'middle', horizontal: 'left' };
    });

    // Data Rows
    rows.forEach(r => {
      const row = worksheet.addRow(r);
      row.eachCell(cell => {
        cell.border = {
          bottom: { style: 'thin', color: { argb: 'FFE2E8F0' } }
        };
      });
    });

    // Auto-fit column widths
    worksheet.columns.forEach(column => {
      let maxLen = 12;
      column.eachCell({ includeEmpty: true }, cell => {
        const len = cell.value ? cell.value.toString().length : 0;
        if (len > maxLen) maxLen = len;
      });
      column.width = Math.min(maxLen + 4, 45);
    });

    // Download buffer
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.showToast('Excel report generated with embedded logo!', 'success');
  } catch (err) {
    console.error('Excel Export Error:', err);
    window.showToast('Could not generate Excel file.', 'error');
  }
}

window.exportHRExcel = function() {
  const deptId = document.getElementById('hrFilterDept')?.value || 'ALL';
  const empId = document.getElementById('hrFilterEmp')?.value || 'ALL';

  if (empId !== 'ALL') {
    const emp = state.employees.find(e => e.id === empId);
    if (!emp) return;
    const dept = state.departments.find(d => d.id === emp.departmentId);
    const receipts = state.tabReceipts.filter(r => r.employeeId === empId);

    const headers = ["Date & Time", "Order ID", "Items Consumed", "Amount (RWF)"];
    const rows = [];
    if (receipts.length > 0) {
      receipts.slice().reverse().forEach(r => {
        const itemsStr = r.items.map(i => `${i.qty}x ${i.name || 'Item'}`).join('; ');
        rows.push([new Date(r.timestamp).toLocaleString(), r.id, itemsStr, r.total]);
      });
    }

    exportExcelWithLogo(
      `Detailed Statement - ${emp.fullName} (${emp.staffId || 'N/A'}) - Dept: ${dept ? dept.name : 'Unknown'}`,
      headers,
      rows,
      `statement_${emp.fullName.replace(/\s+/g, '_')}_${new Date().toISOString().slice(0,10)}.xlsx`
    );
  } else {
    let deptsToExport = state.departments;
    if (deptId !== 'ALL') {
      deptsToExport = state.departments.filter(d => d.id === deptId);
    }

    const headers = ["Department Code", "Department Name", "Staff ID", "Employee Name", "Amount to Deduct (RWF)"];
    const rows = [];
    deptsToExport.forEach(d => {
      const emps = state.employees.filter(e => e.departmentId === d.id && e.currentBalance > 0);
      emps.forEach(e => {
        rows.push([d.code, d.name, e.staffId || 'N/A', e.fullName, e.currentBalance]);
      });
    });

    exportExcelWithLogo(
      'HR Payroll Deductions Summary Report',
      headers,
      rows,
      `hr_payroll_deductions_${new Date().toISOString().slice(0,10)}.xlsx`
    );
  }
};

window.exportDepartmentExcel = function(deptId) {
  const dept = state.departments.find(d => d.id === deptId);
  if (!dept) return;

  const staffList = state.employees.filter(e => e.departmentId === deptId);
  const staffIds = staffList.map(e => e.id);
  const receipts = state.tabReceipts.filter(r => staffIds.includes(r.employeeId) || r.departmentId === deptId);

  const headers = ["Date & Time", "Staff ID", "Employee Name", "Order ID", "Items Consumed", "Amount (RWF)"];
  const rows = [];
  receipts.slice().reverse().forEach(r => {
    const itemsStr = r.items.map(i => `${i.qty}x ${i.name || 'Item'}`).join('; ');
    rows.push([new Date(r.timestamp).toLocaleString(), r.staffId || 'N/A', r.employeeName || 'Staff', r.id, itemsStr, r.total]);
  });

  exportExcelWithLogo(
    `Department Consumption - ${dept.name} (${dept.code})`,
    headers,
    rows,
    `dept_consumption_${dept.code}_${new Date().toISOString().slice(0,10)}.xlsx`
  );
};


// ── Auto-Generation Helpers for Department & Staff Codes ──
window.generateDepartmentCode = function(name) {
  if (!name) return 'DEPT';
  const clean = name.trim().toUpperCase().replace(/[^A-Z0-9\s]/g, '');
  const words = clean.split(/\s+/).filter(w => w.length > 0);

  let baseCode = '';
  if (words.length >= 3) {
    baseCode = (words[0][0] + words[1][0] + words[2][0]).toUpperCase();
  } else if (words.length === 2) {
    if (words[0].length >= 3) baseCode = words[0].slice(0, 3).toUpperCase();
    else baseCode = (words[0] + words[1][0]).slice(0, 3).toUpperCase();
  } else {
    baseCode = clean.slice(0, 3).toUpperCase();
  }

  if (baseCode.length < 2) baseCode = (clean + 'DEP').slice(0, 3);

  // Avoid collision
  let code = baseCode;
  let counter = 1;
  while (state.departments && state.departments.some(d => d.code === code)) {
    code = `${baseCode}-${String(counter).padStart(2, '0')}`;
    counter++;
  }
  return code;
};

window.autoGenerateDeptCode = function() {
  const nameInput = document.getElementById('addDeptName');
  const codeInput = document.getElementById('addDeptCode');
  if (!nameInput || !codeInput) return;
  
  const generated = window.generateDepartmentCode(nameInput.value);
  codeInput.value = generated;
};

window.generateStaffId = function(departmentId) {
  const dept = state.departments.find(d => d.id === departmentId);
  const deptCode = dept ? dept.code : 'EMP';

  const deptEmps = state.employees.filter(e => e.departmentId === departmentId);
  let maxNum = 0;

  deptEmps.forEach(e => {
    if (e.staffId) {
      const parts = e.staffId.split('-');
      if (parts.length >= 2) {
        const num = parseInt(parts[parts.length - 1], 10);
        if (!isNaN(num) && num > maxNum) maxNum = num;
      }
    }
  });

  const nextNum = maxNum + 1;
  const suffix = String(nextNum).padStart(2, '0');
  return `${deptCode}-${suffix}`;
};

window.updateAutoStaffId = function() {
  const deptSelect = document.getElementById('addEmpDeptSelect');
  const staffIdInput = document.getElementById('addEmpStaffId');
  if (!deptSelect || !staffIdInput) return;

  const deptId = deptSelect.value;
  if (deptId) {
    staffIdInput.value = window.generateStaffId(deptId);
  }
};
